        Z('baoyu', '暴雨', 'bàoyǔ', ('averse violente', 'rainstorm')),
        Z('taifeng', '台风', 'táifēng', ('typhon', 'typhoon')),
        Z('wu', '雾', 'wù', ('brouillard', 'fog')),
        Z('chaoshi', '潮湿', 'cháoshī', ('humide', 'damp, humid')),
