        Z('dong-freeze', '冻', 'dòng', ('geler', 'to freeze')),
        Z('yubao', '预报', 'yùbào', ('prévoir ; prévision', 'to forecast; forecast')),
        Z('qiwen', '气温', 'qìwēn', ('température (de l’air)', 'air temperature')),
        Z('lingxia', '零下', 'língxià', ('en dessous de zéro', 'below zero')),
