        Z('xiaohao', '消耗', 'xiāohào', ('consommer, dépenser', 'to consume')),
        Z('jiesheng', '节省', 'jiéshěng', ('économiser', 'to save')),
        Z('chansheng', '产生', 'chǎnshēng', ('produire, engendrer', 'to produce, to give rise to')),
